(()=>{'use strict';
const API=location.hostname==='abuad-life.onrender.com'?'https://abuad-life-api.onrender.com':location.origin;
const KEY='abuadLifeSocial',EPOCH='2026-10-19-account-reset';
if(localStorage.getItem('abuad-account-epoch')!==EPOCH){for(const key of Object.keys(localStorage))if(key===KEY||key==='abuad-life-v1'||key.startsWith('abuad-life-backup-'))localStorage.removeItem(key);localStorage.setItem('abuad-account-epoch',EPOCH)}
let mode='signup';const $=id=>document.getElementById(id),form=$('accountForm');
function setMode(next){mode=next;const login=next==='login';for(const id of ['signupFields','extraFields']){$(id).hidden=login;$(id).querySelectorAll('input,select').forEach(x=>x.disabled=login)}$('loginFields').hidden=!login;$('login').disabled=!login;$('login').required=login;$('password').autocomplete=login?'current-password':'new-password';$('password').minLength=login?1:8;$('heading').textContent=login?'Good to have you back.':'Welcome to campus.';$('subheading').textContent=login?'Sign in and pick up your campus story.':'Create your account and make yourself at home.';$('submitAccount').textContent=login?'Sign in →':'Create my account →';$('switchPrompt').firstChild.textContent=login?'New to campus? ':'Already part of campus? ';$('switchMode').textContent=login?'Create an account':'Sign in';$('signupTab').classList.toggle('active',!login);$('loginTab').classList.toggle('active',login);$('signupTab').setAttribute('aria-pressed',!login);$('loginTab').setAttribute('aria-pressed',login);$('feedback').textContent='';}
$('signupTab').onclick=()=>setMode('signup');$('loginTab').onclick=()=>setMode('login');$('switchMode').onclick=()=>setMode(mode==='signup'?'login':'signup');$('showPassword').onclick=()=>{const show=$('password').type==='password';$('password').type=show?'text':'password';$('showPassword').textContent=show?'Hide':'Show';$('showPassword').setAttribute('aria-label',show?'Hide password':'Show password')};
form.onsubmit=async e=>{e.preventDefault();$('feedback').textContent='';if(mode==='signup'&&$('password').value!==$('confirmPassword').value){$('feedback').textContent='Your passwords do not match.';return}if(new TextEncoder().encode($('password').value).length>72){$('feedback').textContent='Please use a password of no more than 72 bytes.';return}const button=$('submitAccount');button.disabled=true;button.textContent=mode==='signup'?'Creating your account…':'Signing in…';try{const payload=Object.fromEntries(new FormData(form));delete payload.confirmPassword;payload.avatar='🧑🏾‍🎓';const r=await fetch(API+'/api/auth/'+(mode==='signup'?'register':'login'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(60000)});const data=await r.json();if(!r.ok)throw Error(data.error||'Unable to continue.');const owner=localStorage.getItem('abuad-save-owner');if(owner!==data.profile.id)localStorage.removeItem('abuad-life-v1');localStorage.setItem('abuad-save-owner',data.profile.id);localStorage.setItem(KEY,JSON.stringify({token:data.token,profile:data.profile}));location.replace('index.html');}catch(error){$('feedback').textContent=error.name==='TimeoutError'?'The server is taking longer than usual. Please try again.':error.message||'Could not connect. Please try again.';}finally{button.disabled=false;button.textContent=mode==='signup'?'Create my account →':'Sign in →'}};
if(new URLSearchParams(location.search).get('mode')==='login')setMode('login');
})();
